    lnd_register_interest: 'Register interest',
    lnd_plan1_desc: 'For athletes just getting started. Connect Garmin once —LabX syncs automatically every time you log in— and have your full CTL/ATL/TSB history always on hand.',
    lnd_plan1_f1: 'Dashboard + full history', lnd_plan1_f2: 'Automatic Garmin Connect sync',
    lnd_plan1_f3: 'CTL / ATL / TSB (Performance Management)',
    lnd_plan1_f4: 'Training plan, Nutrition, Analytics', lnd_plan1_f5: 'Blood Labs + AI Coach',
    lnd_plan2_desc: 'For age-groupers training seriously. Periodized training plan, nutrition tuned to your load, race time predictor and community — all cross-referenced with your real Garmin data.',
    lnd_plan2_f1: 'Everything in the Athlete plan', lnd_plan2_f2: 'Training plan + Nutrition',
    lnd_plan2_f3: 'Advanced analytics + Race predictor', lnd_plan2_f4: 'Recovery (HRV) + Mental state',
    lnd_plan2_f5: 'Blood Labs + AI Coach (Elite plan)',
    lnd_plan3_desc: 'The platform at full power. Blood Labs correlated with your PMC, AI Coach with CTL forecast and early injury-risk alerts, adaptive plan that adjusts itself to your real fatigue, and a Zwift-style indoor workout builder.',
    lnd_plan3_f1: 'Everything in the Agegroup plan', lnd_plan3_f2: 'Blood Labs + biomarkers (impacts your plan)',
    lnd_plan3_f3: 'AI Coach — CTL forecast + injury risk', lnd_plan3_f4: 'Automatic adaptive plan',
    lnd_plan3_f5: 'Indoor Workout Builder (Zwift-style)',
    lnd_plan4_desc: 'The Coach panel is an additional role on top of your own account. Activating it gives you full access to every athlete feature (Blood Labs, AI Coach, Adaptive) automatically, on top of managing your squad — no separate athlete plan required.',
    lnd_plan4_f1: 'Squad Overview — risk across all your athletes', lnd_plan4_f2: 'Structured workout prescriptions',
    lnd_plan4_f3: 'Messaging and notifications with your athletes', lnd_plan4_f4: 'Manage 50+ athletes',
    lnd_plan4_f5: 'Full athlete-level access (Elite) included',
    lnd_test_label: 'Athletes who trust us', lnd_test_title: 'Real results.',
    lnd_test1_quote: '"LabX gave me the visibility TrainingPeaks never had. Seeing my CTL in real time with integrated GPS completely changed my prep for the Buenos Aires 70.3."',
    lnd_test1_role: 'Ironman 70.3 · Santiago, Chile',
    lnd_test2_quote: '"As a coach I manage 12 athletes and the squad dashboard saves me 3 hours a week. Seeing the whole team\'s risk grid in one click is invaluable."',
    lnd_test2_role: 'Triathlon coach · Buenos Aires',
